function workbookContext(){
  const sheets=state.sheets.map(s=>({name:s.name,cells:Object.entries(s.cells).slice(0,500).map(([address,cell])=>({address,raw:cell.raw||"",value:valueAt(...address.split(":").map(Number))}))}));
  return {workbook:$("workbookTitle").textContent,activeSheet:sheet().name,selection:selectionName(),sheets,availableActions:["selectCell","setCell","format","clear","find","sort","autoSum","insertRow","insertColumn","addSheet","zoom","showFormulas"]};
}
function aiMessage(text,kind="assistant"){const el=document.createElement("div");el.className=`ai-message ${kind}`;el.textContent=text;$("aiMessages").append(el);$("aiMessages").scrollTop=$("aiMessages").scrollHeight}
function aiProgress(text,visible=true){$("aiProgressText").textContent=text;$("aiProgress").hidden=!visible}
function aiAction(action){
  if(!action)return;
  if(Array.isArray(action)){action.forEach(aiAction);return}
  if(action.actions){action.actions.forEach(aiAction);return}
  if(!action.name)return;
  const args=action.args||action.parameters||action;
  if(action.name==="selectCell"){const p=parseAddr(args.address||"A1");if(p)select(p.row,p.col,true)}
  else if(action.name==="setCell"){const p=parseAddr(args.address||"A1");if(p)setCell(p.row,p.col,args.value??"");render()}
  else if(action.name==="setFormula"){const p=parseAddr(args.address||"A1"),formula=String(args.formula||"");if(p&&formula){setCell(p.row,p.col,formula.startsWith("=")?formula:`=${formula}`);render()}}
  else if(action.name==="fillFormula"){
    const start=parseAddr(args.start||"A1"),end=parseAddr(args.end||args.start||"A1"),formula=String(args.formula||"");
    if(start&&end&&formula){for(let r=Math.min(start.row,end.row);r<=Math.max(start.row,end.row);r++)for(let c=Math.min(start.col,end.col);c<=Math.max(start.col,end.col);c++){const offsetR=r-start.row,offsetC=c-start.col;const shifted=formula.replace(/([A-Z]+)(\d+)/g,(_,letters,row)=>{const cell=parseAddr(`${letters}${row}`);return cell?addr(cell.row+offsetR,cell.col+offsetC):`${letters}${row}`});setCell(r,c,shifted.startsWith("=")?shifted:`=${shifted}`)}render()}
  }
  else if(action.name==="calculate"){render();aiMessage("Workbook formulas recalculated.")}
  else if(action.name==="setRange"){
    const start=parseAddr(args.start||args.address||"A1"),values=Array.isArray(args.values)?args.values:[];
    if(start)values.forEach((row,r)=>Array.isArray(row)&&row.forEach((value,c)=>setCell(start.row+r,start.col+c,value??"")));render();
  }
  else if(action.name==="createTable"){
    const start=parseAddr(args.start||"A1"),values=Array.isArray(args.values)?args.values:[];
    if(start)values.forEach((row,r)=>Array.isArray(row)&&row.forEach((value,c)=>setCell(start.row+r,start.col+c,value??"")));
    if(start&&values.length){const endRow=start.row+values.length-1,endCol=start.col+Math.max(...values.map(row=>row.length))-1;select(start.row,start.col);state.selection={r1:start.row,c1:start.col,r2:endRow,c2:endCol,mode:"cell"};commandFormat("bold",true);commandFormat("fill","#d9ebff");select(start.row,start.col)}
    render();
  }
  else if(action.name==="format"){const p=parseAddr(args.address||selectionName());if(p)select(p.row,p.col);commandFormat(args.property,args.value)}
  else if(action.name==="clear")commandClear(args.kind==="format"?"format":"contents");
  else if(action.name==="find")commandFind(Boolean(args.replace));
  else if(action.name==="sort")commandSort(Boolean(args.reverse));
  else if(action.name==="autoSum")commandAutoSum();
  else if(action.name==="insertRow")commandInsert("row");
  else if(action.name==="insertColumn")commandInsert("column");
  else if(action.name==="addSheet"){state.sheets.push({name:args.name||`Sheet${state.sheets.length+1}`,cells:{}});state.sheet=state.sheets.length-1;renderSheets();render()}
  else if(action.name==="zoom"){$("zoom").value=Math.max(70,Math.min(140,Number(args.value)||100));$("zoom").dispatchEvent(new Event("input"))}
  else if(action.name==="showFormulas"){document.body.classList.toggle("show-formulas",args.enabled===undefined?!document.body.classList.contains("show-formulas"):Boolean(args.enabled));render()}
  else if(action.name==="setColumnWidth"){COL_W=Math.max(30,Math.min(400,Number(args.value)||92));render()}
  else if(action.name==="setRowHeight"){ROW_H=Math.max(5,Math.min(200,Number(args.value)||22));render()}
}
function parseAiReply(text){
  const cleaned=text.replace(/```(?:json)?/gi,"").replace(/```/g,"").trim();
  const match=cleaned.match(/\{[\s\S]*\}|\[[\s\S]*\]/);if(!match)return null;
  try{return JSON.parse(match[0])}catch{return null}
}
function localFormulaFallback(prompt){
  const formulaMatch=prompt.match(/(?:put|write|set|add|enter|calculate|insert)[^=\n]*?(?:in|at|to)\s*([A-Z]{1,3}\d+)[^=\n]*?(=\s*[A-Z]+\s*\([^)]*\)|=\s*[^,\n]+)/i);
  if(formulaMatch)return {message:`Added the formula ${formulaMatch[2].trim()} to ${formulaMatch[1].toUpperCase()}.`,action:{name:"setFormula",args:{address:formulaMatch[1],formula:formulaMatch[2].trim()}}};
  const direct=prompt.match(/\b([A-Z]{1,3}\d+)\b\s*(?:formula|=)\s*(=\s*.+)$/i);
  if(direct)return {message:`Added the formula to ${direct[1].toUpperCase()}.`,action:{name:"setFormula",args:{address:direct[1],formula:direct[2].trim()}}};
  const cellAndFunction=prompt.match(/\b([A-Z]{1,3}\d+)\b[^\n]*(SUM|AVERAGE|MIN|MAX|COUNT|COUNTA|PRODUCT|ROUND|IF|ABS|SQRT)\s*\(([^)]+)\)/i);
  if(cellAndFunction){const formula=`=${cellAndFunction[2].toUpperCase()}(${cellAndFunction[3]})`;return {message:`Added the formula ${formula} to ${cellAndFunction[1].toUpperCase()}.`,action:{name:"setFormula",args:{address:cellAndFunction[1],formula}}}}
  const setCell=prompt.match(/(?:set|put|write|enter)\s+(?:cell\s+)?([A-Z]{1,3}\d+)\s+(?:to|as)\s+(.+)$/i);
  if(setCell&&!String(setCell[2]).trim().startsWith("="))return {message:`Set ${setCell[1].toUpperCase()} to ${setCell[2].trim()}.`,action:{name:"setCell",args:{address:setCell[1],value:setCell[2].trim()}}};
  return null;
}
function localRequestFallback(prompt){
  return localFormulaFallback(prompt);
}
async function askGroq(prompt){
  if(!groqApiKey){
    aiMessage(prompt,"user");
    const local=localRequestFallback(prompt);
    if(local?.action){aiProgress("Applying workbook changes...");aiAction(local.action);aiMessage(local.message||"Workbook updated.");$("aiContextStatus").textContent="Workbook updated";aiProgress("",false)}
    else{aiMessage("Connect Groq to use workbook-wide agent actions. Basic formula requests are available locally.","error");$("aiContextStatus").textContent="Groq not connected"}
    return;
  }
  aiMessage(prompt,"user");aiProgress("Thinking through your workbook...");$("aiContextStatus").textContent="Working";
  const system=`You are Excel Flow's workbook agent. You must perform the user's spreadsheet request by returning an executable action, not just advice. Return ONLY one valid JSON object with no markdown: {"message":"short result","action":{"name":"setCell","args":{"address":"A1","value":"Example"}}}. For multiple edits use {"message":"short result","action":{"actions":[{"name":"setCell","args":{"address":"A1","value":"Example"}},{"name":"setFormula","args":{"address":"B1","formula":"=SUM(A1:A5)"}}]}}. If the request is conversational and needs no workbook change, use action:null. Never claim an edit was made unless you return the action that makes it. Never invent existing cell values. For requests to create a table, use createTable with start and a 2D values array. For bulk pasted data use setRange. For formulas, always use setFormula(address,formula) for one formula or fillFormula(start,end,formula) for a repeated relative formula; formulas must start with =. Use cell references and ranges such as =SUM(B2:D2). Supported functions include SUM, AVERAGE, MIN, MAX, COUNT, COUNTA, PRODUCT, ABS, ROUND, SQRT, POWER, MOD, AND, OR, NOT, IF, CONCAT, CONCATENATE, LEFT, RIGHT, LEN, UPPER, LOWER, TRIM, RAND, and RANDBETWEEN. Use calculate() after a group of formula edits when useful. Available actions: selectCell(address), setCell(address,value), setFormula(address,formula), fillFormula(start,end,formula), setRange(start,values), createTable(start,values), format(address,property,value), clear(kind), find(replace), sort(reverse), autoSum(), calculate(), insertRow(), insertColumn(), addSheet(name), zoom(value), showFormulas(enabled), setColumnWidth(value), setRowHeight(value). Use format properties bold, italic, underline, color, fill, align, wrap, format. Workbook context: ${JSON.stringify(workbookContext())}`;
  aiHistory.push({role:"user",content:prompt});
  try{
    let response,data,lastError;
    for(const model of GROQ_MODELS){
      const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);
      try{
        response=await fetch("https://api.groq.com/openai/v1/chat/completions",{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${groqApiKey}`},body:JSON.stringify({model,messages:[{role:"system",content:system},...aiHistory],temperature:.2,response_format:{type:"json_object"}}),signal:controller.signal});
        const body=await response.text();try{data=JSON.parse(body)}catch{data={error:{message:body||"Groq returned an unreadable response"}}}
        if(response.ok)break;
        lastError=new Error(`${model}: ${data.error?.message||`HTTP ${response.status}`}`);
      }catch(err){lastError=err.name==="AbortError"?new Error(`${model}: request timed out after 30 seconds`):err}
      finally{clearTimeout(timer)}
    }
    if(!response?.ok)throw lastError||new Error("Groq request failed");
    const text=data.choices?.[0]?.message?.content||"";
    if(!text.trim())throw new Error("Groq returned an empty response.");
    aiHistory.push({role:"assistant",content:text});
    const parsed=parseAiReply(text),fallback=localRequestFallback(prompt),chosen=parsed?.action?parsed:fallback;
    if(chosen?.action){aiProgress("Applying workbook changes...");aiAction(chosen.action);aiMessage(chosen.message||"Workbook updated.");$("aiContextStatus").textContent="Workbook updated"}
    else if(parsed?.message){aiMessage(`${parsed.message}\n\nNo workbook change was executed. Please specify a cell or range and the exact operation.`,"error");$("aiContextStatus").textContent="No change made"}
    else{aiMessage(text||"I could not understand that request. Please specify a cell or range.","error");$("aiContextStatus").textContent="No change made"}
  }catch(err){$("aiContextStatus").textContent="Connection failed";aiMessage(err.message,"error")}finally{aiProgress("",false)}
}
function setupAi(){
  $("aiBtn").onclick=()=>{$("aiPanel").hidden=false;$("aiInput").focus()};
  $("aiClose").onclick=()=>{$("aiPanel").hidden=true};
  $("aiSettings").onclick=()=>{$("aiSetup").hidden=false;$("aiChat").hidden=true;$("groqKey").value="";$("groqKey").placeholder=groqApiKey?"Saved key — enter a new key to replace it":"Paste a Groq API key to connect";$("aiConnect").textContent=groqApiKey?"Replace Groq key":"Connect Groq";$("groqKey").focus()};
  $("aiSettingsClose").onclick=()=>{$("aiSetup").hidden=true;$("aiChat").hidden=false;$("aiInput").focus()};
  $("aiMinimize").onclick=()=>{$("aiPanel").classList.toggle("ai-minimized");$("aiChat").hidden=!$("aiChat").hidden;$("aiSetup").hidden=true};
  $("groqKey").oncopy=e=>e.preventDefault();
  $("groqKey").oncut=e=>e.preventDefault();
  $("aiConnect").onclick=e=>{e.preventDefault();const key=$("groqKey").value.replace(/\s+/g,"");if(!key)return aiMessage("Enter a new Groq API key to replace the saved key.","error");groqApiKey=key;sessionStorage.setItem("excel-groq-api-key",key);$("groqKey").value="";$("aiConnectionLabel").textContent="Connecting...";$("aiContextStatus").textContent="Key saved for this tab";$("aiConnect").disabled=true;setTimeout(()=>{$("aiConnect").disabled=false;$("aiSetup").hidden=true;$("aiChat").hidden=false;$("aiConnectionLabel").textContent="Groq connected";$("aiContextStatus").textContent="Ready to send requests";$("aiDisconnect").hidden=false;$("aiInput").focus()},150)};
  $("aiDisconnect").onclick=()=>{groqApiKey="";sessionStorage.removeItem("excel-groq-api-key");aiHistory.length=0;$("aiConnectionLabel").textContent="Not connected";$("aiContextStatus").textContent="Groq not connected";$("aiDisconnect").hidden=true};
  if(groqApiKey){$("aiConnectionLabel").textContent="Groq connected";$("aiContextStatus").textContent="Ready to send requests";$("aiDisconnect").hidden=false}
  $("aiForm").onsubmit=e=>{e.preventDefault();const input=$("aiInput"),text=input.value.trim();if(!text)return;input.value="";askGroq(text)};
  let drag=null;
  $("aiDragHandle").onpointerdown=e=>{if(e.target.closest("button"))return;const rect=$("aiPanel").getBoundingClientRect();drag={x:e.clientX,y:e.clientY,left:rect.left,top:rect.top};$("aiDragHandle").setPointerCapture(e.pointerId)};
  $("aiDragHandle").onpointermove=e=>{if(!drag)return;$("aiPanel").style.left=Math.max(0,drag.left+e.clientX-drag.x)+"px";$("aiPanel").style.top=Math.max(42,drag.top+e.clientY-drag.y)+"px";$("aiPanel").style.right="auto"};
  $("aiDragHandle").onpointerup=()=>{drag=null};
}
setupAi();
function setupDesignPanel(){
  $("designClose").onclick=()=>{$("designPanel").hidden=true};
  $("designTextColor").onclick=e=>openColorPalette("color",e.currentTarget);
  $("designFillColor").onclick=e=>openColorPalette("fill",e.currentTarget);
  $("designBorder").onclick=()=>commandFormat("border","#4b5563");
  $("designClearBorder").onclick=()=>{eachSelected((r,c)=>{const cell=sheet().cells[key(r,c)];if(cell)delete cell.border});state.dirty=true;$("saveStatus").textContent="Unsaved changes";localStorage.setItem("excel-workbook",JSON.stringify(state.sheets));render()};
  document.querySelectorAll(".design-presets button").forEach(button=>button.onclick=()=>{commandFormat("color",button.dataset.color);commandFormat("fill",button.dataset.fill)});
  $("designBold").onclick=()=>commandFormat("bold");
  $("designItalic").onclick=()=>commandFormat("italic");
  $("designUnderline").onclick=()=>commandFormat("underline");
  let drag=null;
  $("designDragHandle").onpointerdown=e=>{if(e.target.closest("button"))return;const rect=$("designPanel").getBoundingClientRect();drag={x:e.clientX,y:e.clientY,left:rect.left,top:rect.top};$("designDragHandle").setPointerCapture(e.pointerId)};
  $("designDragHandle").onpointermove=e=>{if(!drag)return;$("designPanel").style.left=Math.max(0,drag.left+e.clientX-drag.x)+"px";$("designPanel").style.top=Math.max(42,drag.top+e.clientY-drag.y)+"px";$("designPanel").style.right="auto"};
  $("designDragHandle").onpointerup=()=>{drag=null};
}
setupDesignPanel();

document.addEventListener("keydown",e=>{
  if(state.editing&&document.body.contains(state.editing))return;
  state.editing=null;
  const target=e.target;
  if(target instanceof HTMLInputElement||target instanceof HTMLTextAreaElement||target.isContentEditable)return;
  if(e.key==="Backspace"||e.key==="Delete"){
    e.preventDefault();
    commandClear("contents");
    return;
  }
  if(e.ctrlKey||e.metaKey||e.altKey||e.key.length!==1)return;
  const cell=document.querySelector(".cell.selected");
  if(!cell)return;
  e.preventDefault();
  edit(cell,e.key);
});
